#include "backprop.hpp"
#include "hardware.hpp"
#include "imports.hpp"
#include "performance.hpp"
#include "thermal.hpp"
#include <cmath>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include <direct.h>
static bool tests(){ThermalConfig c;auto a=solve_thermal_rod(c,10),b=solve_thermal_rod(c,20),d=solve_thermal_rod(c,40),e=solve_thermal_rod(c,80);bool thermal=std::abs(a.nodes.front().temperature-100)<1e-10&&std::abs(a.nodes.back().temperature-20)<1e-10&&std::abs(a.max_midpoint_error-1.25)<1e-8&&b.max_midpoint_error<a.max_midpoint_error&&d.max_midpoint_error<b.max_midpoint_error&&e.max_midpoint_error<d.max_midpoint_error;std::vector<Triangle> tris;auto stl=parse_ascii_stl("data/example_ascii.stl",tris);std::vector<TemperatureNode> nodes;auto csv=parse_temperature_csv("data/synthetic_temperature_nodes.csv",nodes);std::ofstream bad("results/malformed_test.csv");bad<<"node_id,x_m,y_m,z_m,temperature_C\n1,0,0,0,nan\n";bad.close();std::vector<TemperatureNode> badnodes;auto malformed=parse_temperature_csv("results/malformed_test.csv",badnodes);bool imports=stl.ok&&stl.count==1&&csv.ok&&csv.count==3&&!malformed.ok;std::cout<<"[TEST] thermal FE + midpoint convergence: "<<(thermal?"PASS":"FAIL")<<"\n[TEST] valid STL/CSV and malformed non-finite rejection: "<<(imports?"PASS":"FAIL")<<"\n";return thermal&&imports;}
static void help(){std::cout<<"Unified Engineering Workbench (C++17 offline console interface)\nCommands:\n  all [cases] [mesh]   run every engineering view and export results\n  thermal               thermal FEA CSV suite\n  geometry <stl>        validate ASCII STL\n  temperatures <csv>    validate nodal temperature CSV\n  performance [cases] [mesh]  serial/parallel benchmark (default 1000,80)\n  hardware              simulated adapter demonstration\n  backprop              gradient check and 100-step training data\n  test                  positive, malformed-input, numerical tests\nOutputs are written under results/.\n";}
int main(int argc,char*argv[]){try{_mkdir("results");std::string cmd=argc>1?argv[1]:"help",msg;if(cmd=="help"||cmd=="--help"){help();return 0;}if(cmd=="test")return tests()?0:1;if(cmd=="thermal"){bool ok=export_thermal_suite("results",msg);std::cout<<msg<<"\n";return ok?0:1;}if(cmd=="geometry"&&argc==3){std::vector<Triangle>x;auto r=parse_ascii_stl(argv[2],x);std::cout<<(r.ok?"OK: ":"ERROR: ")<<r.message<<" count="<<r.count<<"\n";return r.ok?0:1;}if(cmd=="temperatures"&&argc==3){std::vector<TemperatureNode>x;auto r=parse_temperature_csv(argv[2],x);std::cout<<(r.ok?"OK: ":"ERROR: ")<<r.message<<" count="<<r.count<<"\n";return r.ok?0:1;}if(cmd=="performance"){int cases=argc>2?std::stoi(argv[2]):1000,mesh=argc>3?std::stoi(argv[3]):80;bool ok=run_performance_benchmark("results",cases,mesh,msg);std::cout<<msg<<"\n";return ok?0:1;}if(cmd=="hardware"){bool ok=export_hardware_demo("results",msg);std::cout<<msg<<"\n";return ok?0:1;}if(cmd=="backprop"){bool ok=run_backpropagation("results",msg);std::cout<<msg<<"\n";return ok?0:1;}if(cmd=="all"){int cases=argc>2?std::stoi(argv[2]):1000,mesh=argc>3?std::stoi(argv[3]):80;bool ok=export_thermal_suite("results",msg);std::cout<<"[Thermal] "<<msg<<"\n";ok&=run_performance_benchmark("results",cases,mesh,msg);std::cout<<"[Performance] "<<msg<<"\n";ok&=export_hardware_demo("results",msg);std::cout<<"[Hardware] "<<msg<<"\n";ok&=run_backpropagation("results",msg);std::cout<<"[Backprop] "<<msg<<"\n";return ok?0:1;}help();return 2;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
